type R struct{ ID, T string }

func parseInstant(s string) (time.Time, bool) {
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, false
	}
	return t, true
}

func shared(a, b string) int {
	ta, oka := parseInstant(a)
	tb, okb := parseInstant(b)
	switch {
	case oka && okb:
		switch {
		case ta.Before(tb):
			return -1
		case tb.Before(ta):
			return 1
		default:
			return 0
		}
	case oka != okb:
		if oka {
			return -1
		}
		return 1
	default:
		switch {
		case a < b:
			return -1
		case a > b:
			return 1
		default:
			return 0
		}
	}
}

func main() {
	in := []R{
		{"M-1", "2026-10-05T10:00:00+08:00"},
		{"M-2", "坏-b"},
		{"M-1", "2026-10-05T10:00:00Z"},
		{"M-2", "坏-a"},
		{"M-0", "2026-10-05T10:00:00Z"},
		{"M-1", "坏-a"},
	}

	old := append([]R(nil), in...)
	sort.SliceStable(old, func(i, j int) bool {
		ti, oki := parseInstant(old[i].T)
		tj, okj := parseInstant(old[j].T)
		switch {
		case oki && okj:
			if !ti.Equal(tj) {
				return ti.Before(tj)
			}
		case oki != okj:
			return oki
		default:
